class Flagge
{
   Rechteck oben;
   Rechteck mitte;
   Rechteck unten;

   //TODO3 Neue passende Attribute für Italienflagge anlegen

   Rechteck links; 
   Rechteck rechts;

   //TODO4 Attribute für Japanflagge
   Rechteck hintergrund;
   Kreis punkt; 

   Flagge(String land)
   {
      if(land.toLowerCase().toCharArray()[0] == 'd') {
         zeichneDeutschlandFlagge();
      } else if(land.toLowerCase().toCharArray()[0] == 'a') {
         zeichneAustriaFlagge();
      } else if(land.toLowerCase().toCharArray()[0] == 'i') {
         zeichneItalienFlagge(); 
      } else if(land.toLowerCase().toCharArray()[0] == 'j') {
         zeichneJapanFlagge();
      }
   }

   //TODO1 vervollständige die Methode
   public void zeichneDeutschlandFlagge()
   {
      oben = new Rechteck(150, 150, 600, 150);
      mitte = new Rechteck(150, 250, 600, 100);
      unten = new Rechteck(150, 350, 600, 100);
      oben.farbeSetzen(Color.black);
      mitte.farbeSetzen(Color.red);
      unten.farbeSetzen(Color.gold);
   }

   // TODO2 Schreibe eine weitere Methode für die Austria Flagge 
   void zeichneAustriaFlagge() {
      oben = new Rechteck(150, 150, 600, 100);
      mitte = new Rechteck(150, 250, 600, 100);
      unten = new Rechteck(150, 350, 600, 100);
      oben.farbeSetzen(Color.red);
      mitte.farbeSetzen(Color.white);
      unten.farbeSetzen(Color.red);
   }


   // TODO3 Lege statt den Attributen "oben", "mitte", "unten" neue Attribute an. 
   //       Erstelle eine Methode zeichneItalienFlagge()

   void zeichneItalienFlagge() {
      links = new Rechteck(150, 150, 200, 300);
      mitte = new Rechteck(350, 150, 200, 300);
      rechts = new Rechteck(550, 150, 200, 300);
      links.farbeSetzen(Color.green); 
      mitte.farbeSetzen(Color.white);
      rechts.farbeSetzen(Color.red);
   }

   // TODO4 Japanflagge. Attribute nicht vergessen. 
   void zeichneJapanFlagge() {
      hintergrund = new Rechteck(150, 150, 600, 300); 
      punkt = new Kreis(450, 300, 85); 
      hintergrund.farbeSetzen(Color.white);
      punkt.farbeSetzen(Color.red);
   }

}

