public class Rechteck extends Rectangle {

   String farbe;

   public Rechteck(int x, int y, int b, int h)
   {
      super(x, y, b, h);
   }

   public void farbeSetzen(String farbe)
   {
      setFillColor(farbe);
   }

   public void groesseSetzen(int _breite, int _höhe)
   {
      setHeight(_höhe);
      setWidth(_breite);
   }

   public void verschiebenNach(int x, int y)
   {
      moveTo(x, y);
   }
}

public class Kreis extends Circle {

   int radius;
   int xPosition;
   int yPosition;
   String farbe;

   public Kreis(int x, int y, int r)
   {
      super(x, y, r);
      radius = r;
      xPosition = x;
      yPosition = y;
   }

   public void farbeSetzen(String farbe)
   {
      setFillColor(farbe);
   }

   public void radiusSetzen(int radiusNeu)
   {
      radius = radiusNeu;
      setRadius(radius);
   }

   public void verschiebenNach(int x, int y)
   {
      moveTo(x, y);
   }
}
